import type { Recipe } from '../types'

export function getDifficultyColor(difficulty: Recipe['difficulty']) {
  const colors: Record<string, string> = {
    'Muy fácil': 'bg-green-900/50 text-green-400',
    'Fácil': 'bg-emerald-900/50 text-emerald-400',
    'Media': 'bg-yellow-900/50 text-yellow-400',
    'Media-Alta': 'bg-orange-900/50 text-orange-400',
    'Difícil': 'bg-red-900/50 text-red-400',
    'Avanzado': 'bg-purple-900/50 text-purple-400',
  }
  return colors[difficulty] ?? ''
}

